// Package sqlite reads Phase 10's labs.db (its schema: lab/migrations/0001_init.sql, plain SQL) and writes the
// migration into the platform database (queries.sql, generated by sqlc).
package sqlite

import (
	"context"
	"database/sql"
	"fmt"
	"os"
	"time"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/legacy"
	"github.com/IhebBelhadj/opsforge-academy/academy/internal/platform/sqlite"
)

// Reader implements legacy.Reader.
type Reader struct{}

var _ legacy.Reader = Reader{}

// Read reads every learner row of the Phase 10 database at path, opened read-only.
func (Reader) Read(ctx context.Context, path string) (legacy.Source, error) {
	if _, err := os.Stat(path); err != nil {
		return legacy.Source{}, err
	}
	db, err := sql.Open("sqlite", "file:"+path+"?mode=ro")
	if err != nil {
		return legacy.Source{}, err
	}
	defer func() { _ = db.Close() }()
	var src legacy.Source
	if err := each(ctx, db, `SELECT id, lab_id, content_hash, started_at, finished_at, status, hints_used, seconds, xp
		FROM attempts ORDER BY id`, func(rows *sql.Rows) error {
		var a legacy.Attempt
		var started string
		var finished sql.NullString
		var seconds sql.NullFloat64
		if err := rows.Scan(&a.ID, &a.Lab, &a.Hash, &started, &finished, &a.Status, &a.HintsUsed, &seconds, &a.XP); err != nil {
			return err
		}
		var err error
		if a.StartedAt, err = phase10Time(started); err != nil {
			return err
		}
		if finished.Valid {
			t, err := phase10Time(finished.String)
			if err != nil {
				return err
			}
			a.FinishedAt = &t
		}
		if seconds.Valid {
			a.Seconds = &seconds.Float64
		}
		src.Attempts = append(src.Attempts, a)
		return nil
	}); err != nil {
		return legacy.Source{}, fmt.Errorf("attempts: %w", err)
	}
	if err := each(ctx, db, `SELECT attempt_id, step_id, passed, detail, at FROM step_results ORDER BY id`,
		func(rows *sql.Rows) error {
			var s legacy.StepResult
			var detail, at string
			if err := rows.Scan(&s.Attempt, &s.Step, &s.Passed, &detail, &at); err != nil {
				return err
			}
			s.Detail = []byte(detail)
			var err error
			s.At, err = phase10Time(at)
			src.Steps = append(src.Steps, s)
			return err
		}); err != nil {
		return legacy.Source{}, fmt.Errorf("step results: %w", err)
	}
	if err := each(ctx, db, `SELECT id, kind, COALESCE(subject, ''), data, at FROM events ORDER BY id`,
		func(rows *sql.Rows) error {
			var e legacy.Event
			var data, at string
			if err := rows.Scan(&e.ID, &e.Kind, &e.Subject, &data, &at); err != nil {
				return err
			}
			e.Data = []byte(data)
			var err error
			e.At, err = phase10Time(at)
			src.Events = append(src.Events, e)
			return err
		}); err != nil {
		return legacy.Source{}, fmt.Errorf("events: %w", err)
	}
	if err := each(ctx, db, `SELECT badge_id, awarded_at FROM user_badges ORDER BY awarded_at, badge_id`,
		func(rows *sql.Rows) error {
			var a legacy.Award
			var at string
			if err := rows.Scan(&a.Badge, &at); err != nil {
				return err
			}
			var err error
			a.At, err = phase10Time(at)
			src.Awards = append(src.Awards, a)
			return err
		}); err != nil {
		return legacy.Source{}, fmt.Errorf("awards: %w", err)
	}
	return src, nil
}

func each(ctx context.Context, db *sql.DB, query string, row func(*sql.Rows) error) error {
	rows, err := db.QueryContext(ctx, query)
	if err != nil {
		return err
	}
	defer func() { _ = rows.Close() }()
	for rows.Next() {
		if err := row(rows); err != nil {
			return err
		}
	}
	return rows.Err()
}

// phase10Time reads Phase 10's timestamps (strftime '%Y-%m-%dT%H:%M:%SZ').
func phase10Time(s string) (time.Time, error) { return time.Parse(time.RFC3339, s) }

// Store implements legacy.Store.
type Store struct {
	db *sql.DB
}

var _ legacy.Store = (*Store)(nil)

// NewStore writes into the open platform database db.
func NewStore(db *sql.DB) *Store { return &Store{db: db} }

// Done is what earlier runs imported.
func (s *Store) Done(ctx context.Context) (legacy.Done, error) {
	rows, err := New(s.db).LegacyRows(ctx)
	if err != nil {
		return legacy.Done{}, err
	}
	d := legacy.Done{Attempts: map[int64]int64{}, Events: map[int64]bool{}}
	for _, r := range rows {
		switch r.Kind {
		case "attempt":
			d.Attempts[r.LegacyID] = r.NewID
		case "event":
			d.Events[r.LegacyID] = true
		}
	}
	return d, nil
}

// Apply writes the plan for user in one transaction.
func (s *Store) Apply(ctx context.Context, user int64, p legacy.Plan) (legacy.Report, error) {
	done, err := s.Done(ctx)
	if err != nil {
		return legacy.Report{}, err
	}
	ids := done.Attempts
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return legacy.Report{}, err
	}
	defer func() { _ = tx.Rollback() }()
	q := New(tx)
	var r legacy.Report
	for _, a := range p.Attempts {
		params := InsertAttemptParams{UserID: user, LabID: a.Lab, ContentHash: a.Hash, Status: a.Status,
			StartedAt: sqlite.FormatTime(a.StartedAt), HintsUsed: int64(a.HintsUsed)}
		if a.FinishedAt != nil {
			params.FinishedAt = sql.NullString{String: sqlite.FormatTime(*a.FinishedAt), Valid: true}
		}
		if s := legacy.Seconds(a.Seconds); s != nil {
			params.Seconds = sql.NullInt64{Int64: int64(*s), Valid: true}
		}
		if a.Status == "passed" {
			params.Xp = sql.NullInt64{Int64: int64(a.XP), Valid: true}
		}
		id, err := q.InsertAttempt(ctx, params)
		if err != nil {
			if a.Status == "running" {
				return legacy.Report{}, fmt.Errorf("attempt %d (%s) is still running in Phase 10, and a lab is "+
					"running here too: abandon one first: %w", a.ID, a.Lab, err)
			}
			return legacy.Report{}, fmt.Errorf("attempt %d: %w", a.ID, err)
		}
		if err := q.InsertLegacyRow(ctx, InsertLegacyRowParams{Kind: "attempt", LegacyID: a.ID, NewID: id}); err != nil {
			return legacy.Report{}, err
		}
		ids[a.ID] = id
		r.Attempts++
	}
	for _, st := range p.Steps {
		passed := int64(0)
		if st.Passed {
			passed = 1
		}
		if err := q.InsertStepResult(ctx, InsertStepResultParams{AttemptID: ids[st.Attempt], StepID: st.Step,
			Passed: passed, Detail: string(st.Detail), At: sqlite.FormatTime(st.At)}); err != nil {
			return legacy.Report{}, fmt.Errorf("step result: %w", err)
		}
		r.Steps++
	}
	for _, h := range p.Hints {
		if err := q.InsertHint(ctx, InsertHintParams{AttemptID: ids[h.Attempt], StepID: h.Step, Idx: int64(h.Index),
			At: sqlite.FormatTime(h.At)}); err != nil {
			return legacy.Report{}, fmt.Errorf("hint: %w", err)
		}
		r.Hints++
	}
	for _, e := range p.Events {
		data, err := legacy.Remap(e.Data, ids)
		if err != nil {
			return legacy.Report{}, fmt.Errorf("event %d: %w", e.ID, err)
		}
		id, err := q.InsertEvent(ctx, InsertEventParams{UserID: user, Kind: e.Kind, Subject: e.Subject,
			Data: string(data), At: sqlite.FormatTime(e.At)})
		if err != nil {
			return legacy.Report{}, fmt.Errorf("event %d: %w", e.ID, err)
		}
		if err := q.InsertLegacyRow(ctx, InsertLegacyRowParams{Kind: "event", LegacyID: e.ID, NewID: id}); err != nil {
			return legacy.Report{}, err
		}
		r.Events++
	}
	for _, a := range p.Awards {
		n, err := q.InsertAward(ctx, InsertAwardParams{UserID: user, BadgeID: a.Badge, AwardedAt: sqlite.FormatTime(a.At)})
		if err != nil {
			return legacy.Report{}, fmt.Errorf("award %s: %w", a.Badge, err)
		}
		r.Awards += int(n)
	}
	if err := tx.Commit(); err != nil {
		return legacy.Report{}, err
	}
	return r, nil
}
